package com.bank.audit;

import java.util.concurrent.*;
import java.util.logging.*;

public class ThreadSafetyBufferDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws InterruptedException {
        final String accountId = "SAV2001"; // String: immutable, read by all threads safely
        int threads = 6, perThread = 500, expected = threads * perThread;

        SafeAudit safe = new SafeAudit();       // StringBuffer-backed
        UnsafeAudit unsafe = new UnsafeAudit();  // StringBuilder-backed (racy)

        runConcurrently(threads, perThread, safe::record, unsafe::record, accountId);

        log.info(() -> "Expected lines = " + expected);
        log.info(() -> "StringBuffer (safe) lines  = " + safe.lineCount() + " (CORRECT)");
        log.warning(() -> "StringBuilder (unsafe) lines = " + unsafe.lineCount()
                           + " (likely wrong/corrupted)");
    }

    private static void runConcurrently(int threads, int perThread,
                                        java.util.function.Consumer<String> safeOp,
                                        java.util.function.Consumer<String> unsafeOp,
                                        String accountId) throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        CountDownLatch latch = new CountDownLatch(threads);
        for (int t = 0; t < threads; t++) {
            final int id = t;
            pool.submit(() -> {
                for (int i = 0; i < perThread; i++) {
                    String entry = accountId + "-w" + id + "-" + i;
                    safeOp.accept(entry);
                    unsafeOp.accept(entry);
                }
                latch.countDown();
            });
        }
        latch.await();
        pool.shutdown();
    }
}

// ─── Would be SafeAudit.java in a real project ───
class SafeAudit {
    private final StringBuffer buffer = new StringBuffer(8192); // synchronized
    void record(String entry) { buffer.append(entry).append("\n"); } // atomic per call
    long lineCount() { return buffer.toString().lines().count(); }
}

// ─── Would be UnsafeAudit.java in a real project ───
class UnsafeAudit {
    private final StringBuilder buffer = new StringBuilder(8192); // NOT synchronized
    void record(String entry) { buffer.append(entry).append("\n"); } // racy under threads
    long lineCount() { return buffer.toString().lines().count(); }
}
